/**
 * Suggested follow-ups for the newest reply in a thread.
 *
 * Three short actions, generated by the entity's own harness from the tail of
 * the conversation. A click sends the action's prompt as the next user message —
 * the same path as typing it, so context, mentions and attachments behave
 * exactly as they would if the person had written the words.
 *
 * The result is cached per message so a re-render or a return to the thread does
 * not call the model again. Failure is silent by design: a suggestion strip that
 * cannot be produced should simply be absent, never an error in the transcript.
 */
const fs = require('node:fs')
const path = require('node:path')
const workspaces = require('./workspace-store.cjs')
const { runOneShot, lastJson } = require('./oneshot.cjs')

const MAX_CONTEXT = 12_000
const MAX_ACTIONS = 3
const TIMEOUT_MS = 45_000
const TTL_MS = 30 * 60 * 1000
const cache = new Map()

const INSTRUCTION = [
  'You suggest the follow-up messages a person is most likely to send next.',
  '',
  'From the conversation below, write exactly 3 short actions.',
  '- Each label is a verb phrase of at most 6 words, in the user voice.',
  '- Each prompt is the complete message the user would send, self-contained.',
  '- Exactly one action is primary: the single most useful next step.',
  '- Ground every action in this conversation. Do not invent tools or facts.',
  'Answer with JSON only, no prose and no code fences:',
  '{"actions":[{"label":"…","prompt":"…","primary":true}]}',
].join('\n')

function trim(text, limit) {
  const value = String(text || '').replace(/\s+\n/g, '\n').trim()
  if (value.length <= limit) return value
  return `${value.slice(0, Math.round(limit * 0.75))}\n… (trimmed) …`
}

function threadFile(record, id) {
  return path.join(record.path, 'chats', `${id}.json`)
}

function readThread(record, id) {
  try {
    return JSON.parse(fs.readFileSync(threadFile(record, id), 'utf8'))
  } catch {
    return null
  }
}

function cleanActions(actions) {
  if (!Array.isArray(actions)) return []
  const seen = new Set()
  const out = []
  for (const item of actions) {
    const label = String(item?.label || '').replace(/\s+/g, ' ').trim().slice(0, 60)
    const prompt = String(item?.prompt || '').replace(/\s+/g, ' ').trim().slice(0, 500)
    if (!label || !prompt) continue
    const key = `${label}:${prompt}`.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    out.push({ label, prompt, primary: Boolean(item?.primary) })
    if (out.length >= MAX_ACTIONS) break
  }
  /* One primary at most: the first one the model marked, else the first row. */
  let primary = out.findIndex((item) => item.primary)
  if (primary < 0 && out.length) primary = 0
  return out.map((item, index) => ({ ...item, primary: index === primary }))
}

async function suggest({ workspace, threadId } = {}) {
  const id = String(threadId || '')
  if (!id) throw new Error('No thread is open.')
  const record = workspaces.open(workspace)
  const thread = readThread(record, id)
  if (!thread) throw new Error('That thread no longer exists.')

  const spoken = (thread.messages || []).filter(
    (message) => (message.who === 'me' || message.who === 'agent') && String(message.text || '').trim(),
  )
  const last = spoken[spoken.length - 1]
  if (!last || last.who !== 'agent') return { messageId: '', actions: [] }

  const key = `${record.id}:${id}:${last.id || spoken.length}`
  const hit = cache.get(key)
  if (hit && Date.now() - hit.at < TTL_MS) return hit.value

  const recent = spoken.slice(-6)
  const prompt = recent
    .map((message) => `${message.who === 'me' ? 'User' : 'Entity'}: ${trim(message.text, 2200)}`)
    .join('\n\n')

  const result = await runOneShot({
    harness: thread.harness,
    model: thread.model,
    instruction: INSTRUCTION,
    prompt,
    timeoutMs: TIMEOUT_MS,
    label: 'suggested follow-ups',
  })

  const parsed = lastJson(result.text)
  const actions = cleanActions(parsed?.actions)
  const value = { messageId: last.id || '', actions }
  cache.set(key, { at: Date.now(), value })
  if (cache.size > 200) cache.delete(cache.keys().next().value)
  return value
}

module.exports = { suggest, cleanActions }
